void ODE_system::setup_instance_tolerance(QSPParam&){
    // Per-species absolute tolerance: abstol_base × SI_factor
    // This ensures tolerance is meaningful in each species' native scale.
    // E.g., 1e-12 cells × (1/NA) = 1.66e-36 mol → controls to ~1e-12 cells.
    realtype reltol = 1e-6;
    realtype abstol_base = 1e-12;
    N_Vector abstol = N_VNew_Serial(_neq, _sunctx);
    for (int i = 0; i < _neq; i++) {
        NV_DATA_S(abstol)[i] = abstol_base * get_unit_conversion_species(i);
    }
    int flag = CVodeSVtolerances(_cvode_mem, reltol, abstol);
    check_flag(&flag, "CVodeSVtolerances", 1);
    N_VDestroy(abstol);
}

realtype ODE_system::get_compartment_volume(const std::string& name) const {
    if (name == "V_T") {
        realtype AUX_VAR_C_total = 0.0 * PARAM(P_cell) + _species_var[SP_V_T_C1];
        realtype AUX_VAR_M_total = _species_var[SP_V_T_Mac_M1] + _species_var[SP_V_T_Mac_M2];
        realtype AUX_VAR_T_total = 0.0 * PARAM(P_cell) + _species_var[SP_V_T_Treg] + _species_var[SP_V_T_CD8] + _species_var[SP_V_T_nCD8] + _species_var[SP_V_T_Th] + _species_var[SP_V_T_nCD4] + _species_var[SP_V_T_Tfh];
        realtype AUX_VAR_V_T = PARAM(P_V_Tmin) + ((((_species_var[SP_V_T_C_x] + AUX_VAR_C_total) * PARAM(P_vol_cell)) + ((_species_var[SP_V_T_CD8_exh] + _species_var[SP_V_T_CD8_pex] + _species_var[SP_V_T_Th_exh] + AUX_VAR_T_total) * PARAM(P_vol_Tcell)) + AUX_VAR_M_total * PARAM(P_vol_Mcell) + _species_var[SP_V_T_qPSC] * PARAM(P_vol_qPSCcell) + _species_var[SP_V_T_iCAF] * PARAM(P_vol_iCAFcell) + _species_var[SP_V_T_myCAF] * PARAM(P_vol_myCAFcell) + _species_var[SP_V_T_apCAF] * PARAM(P_vol_apCAFcell)) / PARAM(P_Ve_T)) + _species_var[SP_V_T_collagen] / PARAM(P_rho_collagen) + (((_species_var[SP_V_T_nB] + _species_var[SP_V_T_aB] + _species_var[SP_V_T_Plasma]) * PARAM(P_vol_Tcell)) / PARAM(P_Ve_T));
        return AUX_VAR_V_T / 1e-06;
    }
    if (name == "V_C") return PARAM(P_V_C) / 0.001;
    if (name == "V_P") return PARAM(P_V_P) / 0.001;
    if (name == "V_LN") return PARAM(P_V_LN) / 1e-09;
    if (name == "V_e") return PARAM(P_V_e) / 0.001;
    if (name == "A_e") return PARAM(P_A_e) / 1e-12;
    if (name == "A_s") return PARAM(P_A_s) / 1e-12;
    if (name == "syn_CD8_C1") return PARAM(P_syn_CD8_C1) / 1e-12;
    if (name == "syn_CD8_APC") return PARAM(P_syn_CD8_APC) / 1e-12;
    if (name == "syn_M_C") return PARAM(P_syn_M_C) / 1e-12;
    if (name == "V_ID") return PARAM(P_V_ID) / 0.001;
    throw std::out_of_range("unknown compartment: " + name);
}

